import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { fmt } from "../lib/api";
import { toast } from "sonner";

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const submit = async (e) => {
    e.preventDefault();
    try { await login(email, password); toast.success("Welcome back."); navigate("/dashboard"); }
    catch (err) { toast.error(fmt(err.response?.data?.detail) || err.message); }
  };
  return (
    <div style={{ maxWidth: 440, margin: "4rem auto", padding: "0 2rem" }}>
      <div className="overline">Sign In</div>
      <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0 2rem" }}>Return to the network.</h1>
      <form onSubmit={submit}>
        <label>Email</label>
        <input className="input" style={{ marginBottom: 16 }} type="email" required value={email} onChange={e => setEmail(e.target.value)} />
        <label>Password</label>
        <input className="input" style={{ marginBottom: 24 }} type="password" required value={password} onChange={e => setPassword(e.target.value)} />
        <button className="btn-primary" type="submit" style={{ width: "100%" }}>Sign In</button>
      </form>
      <p style={{ marginTop: 24, fontSize: 14 }}>
        New here? <Link to="/register">Request an account</Link>
      </p>
      <div style={{ marginTop: 32, padding: 16, background: "var(--bone)", border: "1px solid var(--border)", fontSize: 12 }}>
        <div className="overline">Demo</div>
        <div>student1@alumni.edu / student123</div>
        <div>alumni1@alumni.edu / alumni123</div>
      </div>
    </div>
  );
}
